const float PI = 3.1415926535;
mat2 rotate(float angle)
{
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c);
}
float sdfCircle(vec2 p, float r)
{
    return length(p) - r;
}
float hookJade(vec2 tempUv, float angle)
{
    float radius = 0.1;
    tempUv *= rotate(angle);
    float w = 1.0 / iResolution.y;
    float c = sdfCircle(tempUv, radius * 2.0);
    float c2 = sdfCircle(tempUv - vec2(-0.1, 0.0), radius);
    float s = max(-c2, c);
    s = max(s, tempUv.y);
    float c3 = sdfCircle(tempUv - vec2(0.1, 0.0), radius);
    s = min(s, c3);

    return smoothstep(w, -w, s);
}

float getHookJade(vec2 tempUv)
{
    tempUv *= 1.8;
    float coord = 0.4;
    float radical3 = 1.732;
    float g = hookJade(tempUv - vec2(0.00, coord), radians(120.));
    g += hookJade(tempUv - vec2(coord * radical3 * 0.5, -coord * 0.5), radians(240.));
    g += hookJade(tempUv - vec2(-coord * radical3 * 0.5, -coord * 0.5), radians(0.));
    return g;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float w = 1.0 / iResolution.y;
    vec2 uv = fragCoord / iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;
    vec3 complexion = vec3(252.0 / 255.0, 224.0 / 255.0, 203.0 / 255.0);

    vec3 col = mix(vec3(0.2, 0.0, 0.5), vec3(0.0), smoothstep(0.0, 1.0, length(uv)));

    float upEyelid = smoothstep(+5.0 * w, -5.0 * w, abs(uv.y - (cos(PI * uv.x) / 4.0 + 0.25)) - 0.02);
    col = mix(col, complexion, upEyelid);

    float downEyelid = smoothstep(+5.0 * w, -5.0 * w, abs(uv.y + (cos(PI * uv.x) / 4.0 + 0.25)) - 0.02);
    col = mix(col, complexion, downEyelid);

    float eyelid = smoothstep(+5.0 * w, -5.0 * w, abs(sdfCircle(uv, 0.5)) - 0.02);
    col = mix(col, complexion, eyelid);

    float backGround = smoothstep(+w, -w, sdfCircle(uv, 0.4));
    col = mix(col, vec3(1.0, 0.0, 0.0), backGround);

    float ring = abs(sdfCircle(uv, 0.4)) - 0.01;
    float edge = smoothstep(+10.0 * w, -10.0 * w, ring);
    col = mix(col, vec3(0.0), edge);

    float shadow = step(length(uv), 0.4) * smoothstep(0.3, 0.4, length(uv)) * 0.8;
    col = mix(col, vec3(0.0), shadow);

    vec2 hookJadeUv = uv;
    hookJadeUv *= rotate(iTime * 1.2);
    float hookJade = getHookJade(hookJadeUv);
    col = mix(col, vec3(0.0), hookJade);

    float center = smoothstep(+w, -w, sdfCircle(uv, 0.08));
    col = mix(col, vec3(0.0, 0.0, 0.0), center);

    float centerRing = smoothstep(+w, -w, abs(sdfCircle(uv, 0.2)) - 0.01);
    col = mix(col, vec3(0.0), centerRing);

    float highLight = smoothstep(0.15, 0.0, length(uv - vec2(0.18, 0.15)));
    col = mix(col, vec3(0.7), highLight);

    fragColor = vec4(col, 1.0);
}
